301		snapA.Settlements[1], snapA.Settlements[2] = snapA.Settlements[2], snapA.Settlements[1]
302		snapA.Settlements = append(snapA.Settlements, Record{ID: "fake-pay"})
303		snapA.Refunds[0].ID = "HACK-REF"
304		snapA.Refunds[0].SettlementID = "p2"
305		snapA.Refunds[0].Reason = "forged"
306		snapA.Refunds[0].Account = "zz"
307		snapA.Refunds[0].Asset = "btc"
308		snapA.Refunds[0].Amount = 1
309		snapA.Refunds[0].Fee = 1
310		snapA.Refunds[0].Charged = 2
311		snapA.Refunds[0].AfterSeq = 99
312		snapA.Refunds[0].Seq = 99
313		snapA.Refunds = append(snapA.Refunds, RefundRecord{ID: "fake-ref"})
314	
315		// 此前独立取得的另一份结果不能被改写波及（余额与历史一起受保护）。
316		assertSnap(t, snapB, wantFrozen, "snapB after editing snapA")
317	
318		// 再次查询仍得到真实业务产生的数据：原编号、账户、资产、金额、手续费、
319		// 成功序号，以及退款原因和关联原付款全部完整。
320		snapC := mustQuery(t, l)
321		assertSnap(t, snapC, wantFrozen, "ledger after editing snapA")
322		rp1 := snapC.Settlements[0]
323		if rp1.ID != "p1" || rp1.Account != "aa" || rp1.Asset != "usdc" ||
324			rp1.Amount != 1000 || rp1.Fee != 10 || rp1.FeeBps != 100 || rp1.Seq != 1 {
325			t.Fatalf("real p1 record lost after caller edit: %+v", rp1)
326		}
327		rr1 := snapC.Refunds[0]
328		if rr1.ID != "r1" || rr1.Reason != "bad charge" || rr1.SettlementID != "p1" ||
329			rr1.Account != "aa" || rr1.Asset != "usdc" || rr1.Amount != 1000 ||
330			rr1.Fee != 10 || rr1.Charged != 1010 || rr1.Seq != 1 {
331			t.Fatalf("real r1 record lost after caller edit: %+v", rr1)
332		}
333	
334		// 对返回数据的改动不能改变业务判定：
335		// 已退款的原付款按原请求再提交，仍返回 duplicate 和原结算记录，不再次扣款。
336		dup := mustSettle(t, l, 100, intent("p1", "aa", "usdc", 1000))
337		if dup.Status != StatusDuplicate || dup.Record == nil ||
338			dup.Record.Seq != 1 || dup.Record.Charged != 1010 {
339			t.Fatalf("refunded payment retry want duplicate with original record: %+v", dup)
340		}
341		if bal, _ := l.Balance("aa", "usdc"); bal != 3000 {
342			t.Fatalf("duplicate after snapshot edit charged again: bal=%d", bal)
343		}
344	
345		// 用新的退款编号申请退回同一付款：仍为 already_refunded，不增加余额。
346		rx := mustRefundOne(t, l, "rx", "p1", "trying again")
347		if rx.Status != StatusAlreadyRefunded {
348			t.Fatalf("want already_refunded, got %+v", rx)
349		}
350		if bal, _ := l.Balance("aa", "usdc"); bal != 3000 {
351			t.Fatalf("already_refunded after snapshot edit changed balance: %d", bal)
352		}
353	
354		// 后续付款仍按真实余额结算（篡改既没有抬高也没有压低可用余额）。
355		p4 := mustSettle(t, l, 0, intent("p4", "aa", "usdc", 3000))
356		if p4.Status != StatusSettled || p4.Record.Seq != 4 {
357			t.Fatalf("payment must settle against the real balance: %+v", p4)
358		}
359		final := mustQuery(t, l)
360		if final.Balances[0].Balance != 0 || final.Balances[1].Balance != 598 {
361			t.Fatalf("final balances: %+v", final.Balances)
362		}
363		if len(final.Settlements) != 4 || len(final.Refunds) != 1 {
364			t.Fatalf("final history counts: settlements=%d refunds=%d",
365				len(final.Settlements), len(final.Refunds))
366		}
367	}
368	
369	// TestQueryEditCannotRaiseSpendingLimit 验证篡改返回数据（改大余额、伪造记录）
370	// 不能提升调用者的购买力，也不能让伪造编号在真实账本中被当成已结算。
371	func TestQueryEditCannotRaiseSpendingLimit(t *testing.T) {
372		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
373		l := openOrFail(t, path)
374	
375		if r := mustSettle(t, l, 0, intent("p1", "aa", "usdc", 30)); r.Status != StatusSettled {
376			t.Fatalf("p1: %+v", r) // 真实余额 70
377		}
378	
379		snap := mustQuery(t, l)
380		for i := range snap.Balances {
381			if snap.Balances[i].Account == "aa" && snap.Balances[i].Asset == "usdc" {
382				snap.Balances[i].Balance = 1_000_000
383			}
384		}
385		snap.Balances = append(snap.Balances, BalanceView{Account: "ghost", Asset: "gold", Balance: 7})
386		snap.Settlements[0].Charged = 0
387		snap.Settlements[0].Amount = 0
388		// 追加一条伪造成功记录：若查询与账本共享底层数组，这会直接污染真实历史。
389		snap.Settlements = append(snap.Settlements, Record{
390			ID: "fake", Account: "aa", Paymaster: "pm", Asset: "usdc",
391			Amount: 10, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 10, Seq: 99,
392		})
393	
394		// 真实余额未被抬高：超出 70 的付款仍失败。
395		if r := mustSettle(t, l, 0, intent("p2", "aa", "usdc", 71)); r.Status != StatusFunds {
396			t.Fatalf("inflated snapshot balance must not enable overspend: %+v", r)
397		}
398	
399		// 伪造编号没有进入真实历史：同编号同字段的请求按首次付款处理并成功，
400		// 而不是 duplicate；扣款依据真实余额 70。
401		fake := mustSettle(t, l, 0, intent("fake", "aa", "usdc", 10))
402		if fake.Status != StatusSettled || fake.Record.Seq != 2 {
403			t.Fatalf("forged record must not exist in the real ledger: %+v", fake)
404		}
405		if bal, _ := l.Balance("aa", "usdc"); bal != 60 {
406			t.Fatalf("real balance=%d want 60", bal)
407		}
408		again := mustQuery(t, l)
409		if len(again.Settlements) != 2 || again.Settlements[0].Amount != 30 || again.Settlements[0].Charged != 30 {
410			t.Fatalf("real p1 record must stay intact: %+v", again.Settlements)
411		}
412		if len(again.Balances) != 1 {
413			t.Fatalf("forged balance entry leaked into the ledger: %+v", again.Balances)
414		}
415	}
416	
417	// TestQueryAndCallerEditsDoNotRewriteLedgerFile 验证仅查询或修改返回数据时，
418	// 账本文件字节内容与成功记录数量都保持不变。
419	func TestQueryAndCallerEditsDoNotRewriteLedgerFile(t *testing.T) {
420		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
421		l := openOrFail(t, path)
422	
423		// 先产生一笔付款与一笔退款，使余额、结算、退款三类数据都存在。
424		if r := mustSettle(t, l, 100, intent("p1", "aa", "usdc", 300)); r.Status != StatusSettled {
425			t.Fatalf("p1: %+v", r) // charged 303
426		}
427		if r := mustRefundOne(t, l, "r1", "p1", "review"); r.Status != StatusRefundSuccess {
428			t.Fatalf("r1: %+v", r)
429		}
430	
431		before, err := os.ReadFile(path)
432		if err != nil {
433			t.Fatal(err)
434		}
435	
436		// 反复查询，每次都对自己的返回结果做破坏性改写；查询不得触发任何写盘。
437		for i := 0; i < 3; i++ {
438			snap := mustQuery(t, l)
439			for j := range snap.Balances {
440				snap.Balances[j].Balance = int64(-(i + 1))
441				snap.Balances[j].Account = "mutated"
442			}
443			snap.Balances = append(snap.Balances, BalanceView{Account: "x", Asset: "y", Balance: 9})
444			for j := range snap.Settlements {
445				snap.Settlements[j].ID = "MUTATED"
446				snap.Settlements[j].Charged = -1
447				snap.Settlements[j].Seq = int64(100 + i)
448			}
449			snap.Settlements = append(snap.Settlements, Record{ID: "mutated-pay"})
450			for j := range snap.Refunds {
451				snap.Refunds[j].ID = "MUTATED-REF"
452				snap.Refunds[j].Reason = ""
453				snap.Refunds[j].SettlementID = "ghost"
454			}
455			snap.Refunds = append(snap.Refunds, RefundRecord{ID: "mutated-ref"})
456			if _, err := json.Marshal(snap); err != nil {
457				t.Fatal(err)
458			}
459		}
460	
461		after, err := os.ReadFile(path)
462		if err != nil {
463			t.Fatal(err)
464		}
465		if !bytes.Equal(before, after) {
466			t.Fatalf("ledger file changed after queries and caller edits:\nbefore=%s\nafter =%s", before, after)
467		}
468	
469		// 成功记录数量与内容保持不变。
470		snap := mustQuery(t, l)
471		if len(snap.Settlements) != 1 || snap.Settlements[0].ID != "p1" || snap.Settlements[0].Charged != 303 {
472			t.Fatalf("settlement record changed: %+v", snap.Settlements)
473		}
474		if len(snap.Refunds) != 1 || snap.Refunds[0].ID != "r1" || snap.Refunds[0].SettlementID != "p1" {
475			t.Fatalf("refund record changed: %+v", snap.Refunds)
476		}
477		if bal, _ := l.Balance("aa", "usdc"); bal != 1000 {
478			t.Fatalf("balance changed: %d", bal)
479		}
480	}
