	res, _ := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p", "aa", "usdc", 50)}})
	if res.Results[0].Status != StatusStorage {
		t.Fatalf("want storage_error, got %s", res.Results[0].Status)
	}
