247		if failSecond {
248			// p2 之前只是“保存失败”，预览里又“预计成功”过；二者都不能占用编号：
249			// 现在真实提交 p2 必须 settled（而非 duplicate），成功序号 2，余额 40→10。
250			res, err := fromDisk.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
251				intent("p2", acct, asset, p2Amount),
252			}})
