260		} else {
261			// 两笔都已成功：p2 原样重复提交仍 duplicate、携带原记录、不再扣款。
262			res, err := fromDisk.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
263				intent("p2", acct, asset, p2Amount),
264			}})
265			if err != nil {
266				t.Fatalf("repeat p2: %v", err)
267			}
268			if r := res.Results[0]; r.Status != StatusDuplicate {
269				t.Fatalf("settled p2 repeat must be duplicate, got %+v", r)
270			}
271			assertRecord(t, "repeat p2 original record", res.Results[0].Record, wantP2)
272		}
273	
274		// 此刻两种结局收敛到同一状态：余额 10。预览里“预计余额不足”的 p3 从未预留，
275		// 真实提交 p3=15 依旧因 10<15 而余额不足，且不留记录、序号仍停在 2。
276		p3, err := fromDisk.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
277			intent("p3", acct, asset, p3Amount),
278		}})
279		if err != nil {
280			t.Fatalf("submit p3: %v", err)
281		}
282		if r := p3.Results[0]; r.Status != StatusFunds || r.Record != nil {
283			t.Fatalf("real p3: %+v", r)
284		}
285		if bal, _ := fromDisk.Balance(acct, asset); bal != 10 {
286			t.Fatalf("balance after resubmits=%d want 10", bal)
287		}
288		final := mustQuery(t, fromDisk)
289		if !reflect.DeepEqual(final.Settlements, []Record{wantP1, wantP2}) {
290			t.Fatalf("final history:\n got %+v\nwant [p1,p2]", final.Settlements)
291		}
292	
293		// 再关句柄重开，确认磁盘文件与内存一致：p1 金额/扣款总额/序号、p2 全部原样，
294		// 没有任何预测成功记录或 p3，余额 10。
295		fromDisk.Close()
