299			t.Fatalf("reopened ledger history:\n got %+v\nwant [p1,p2]", diskFinal.Settlements)
300		}
301		if bal, _ := reopened.Balance(acct, asset); bal != 10 {
302			t.Fatalf("reopened balance=%d want 10", bal)
