304	}
305	
306	// TestPreviewWaitsForInFlightBatchBothSettled：两笔真实付款都成功（余额剩 10）。
307	// 与批次并发发起的预览必须等批次完成：p1、p2 均 duplicate 并携带各自原结算
308	// 记录，p3=15 因余额 10 而 insufficient_balance。
309	func TestPreviewWaitsForInFlightBatchBothSettled(t *testing.T) {
310		runPreviewDuringSaveInterleave(t, false)
311	}
312	
313	// TestPreviewWaitsForInFlightBatchSecondSaveFails：p1 成功、p2 保存失败。
314	// 真实批次保留 p1、p2 报 storage_error、余额 40；并发预览基于该完整状态：
315	// p1 duplicate，p2 首次预计成功（序号 2），模拟余额 40→10 后 p3 余额不足；
316	// 失败的真实 p2 不被当成已结算，预览也不继承 storage_error。
317	func TestPreviewWaitsForInFlightBatchSecondSaveFails(t *testing.T) {
